package epidemic.editor;

import epidemic.u1.NativeViewport;
import java.awt.*;
import java.nio.file.*;
import java.util.*;
import java.util.List;
import java.util.concurrent.*;
import javax.swing.*;

/** Owned native HWNDs, real Bridge and Renderer; no Robot or Computer Use. */
public final class RuntimePresentationTests {
    private static void check(boolean condition,String message){if(!condition)throw new IllegalStateException(message);}
    private static <T>T edt(Callable<T> action)throws Exception{var task=new FutureTask<T>(action);SwingUtilities.invokeAndWait(task);return task.get();}
    private static Bridge.Reply call(Bridge b,int op,String... args)throws Exception{return b.call(op,args).get(20,TimeUnit.SECONDS);}
    private record WindowView(JFrame frame,RuntimeGameView game) {}
    private static JFrame show(JComponent component){var frame=new JFrame("F-II.4 owned presentation qualification");frame.setDefaultCloseOperation(JFrame.DISPOSE_ON_CLOSE);frame.add(component);frame.setSize(1100,750);frame.setVisible(true);return frame;}
    private static JTable table(Component root,String name){if(root instanceof JTable value&&name.equals(value.getName()))return value;if(root instanceof Container group)for(var child:group.getComponents()){var value=table(child,name);if(value!=null)return value;}return null;}
    private static void history(UiPanels panel,Bridge.Reply reply)throws Exception{edt(()->{panel.refresh(reply.snapshot());panel.runtime(reply.runtime());return null;});}
    public static void main(String[] args)throws Exception{
        Path work=Path.of(args[1]).toAbsolutePath();Files.createDirectories(work);Path project=Path.of(Files.readString(work.resolve("runtime-project.txt")).trim());List<JFrame> owned=new ArrayList<>();
        try(var b=new Bridge(Path.of(args[0]).toAbsolutePath(),work.resolve("presentation"),state->{},Runnable::run)){
            b.connect().get(20,TimeUnit.SECONDS);call(b,2,project.toString());call(b,13);call(b,41,"pause",Long.toUnsignedString(b.latest().runtime().session()));
            var command=(UiPanels.RuntimeCommand)(connection,generation,session,action,arguments)->{var payload=new ArrayList<String>();payload.add(action);payload.add(Long.toUnsignedString(session));payload.addAll(List.of(arguments));return b.runtimeCommand(connection,generation,payload);};
            long[] initial=edt(NativeViewport::metrics);var first=edt(()->new RuntimeGameView(command));var second=edt(()->new RuntimeGameView(command));var inspector=edt(RuntimeInspector::new);var profiler=edt(()->new RuntimeProfiler(()->List.of(first.viewport(),second.viewport()),()->false));var debugger=edt(()->new RuntimeDebugger(command,link->{}));
            var logs=edt(()->new UiPanels(new Catalog(),new FeatureRegistry(),doc->{},selection->{},()->{},()->{},kind->{},()->{}));long[] marker={0};
            var frame=b.latest();history(logs,frame);edt(()->{first.refresh(frame.snapshot(),frame.runtime());second.refresh(frame.snapshot(),frame.runtime());inspector.refresh(frame.runtime());debugger.refresh(frame.runtime(),frame.snapshot());owned.add(show(first));var other=new JPanel(new GridLayout(1,2));other.add(second);var details=new JPanel(new GridLayout(2,1));details.add(inspector);details.add(debugger);other.add(details);owned.add(show(other));return null;});
            Thread.sleep(250);edt(()->{first.viewport().draw();second.viewport().draw();check(first.viewport().rootWindow()!=second.viewport().rootWindow(),"Game views did not acquire independent HWNDs");check(NativeViewport.metrics()[0]==initial[0]+2,"Game surfaces not acquired");first.viewport().presentationRate(60);second.viewport().presentationRate(120);return null;});
            call(b,41,"input",Long.toUnsignedString(frame.runtime().session()),"1","0");var before=b.latest().runtime().entities().getFirst();call(b,41,"step",Long.toUnsignedString(frame.runtime().session()));var after=b.latest().runtime().entities().getFirst();check(after.x()>before.x(),"Native Movement did not consume input at Step Tick");
            var current=b.latest();edt(()->{first.refresh(current.snapshot(),current.runtime());second.refresh(current.snapshot(),current.runtime());inspector.refresh(current.runtime());check(String.valueOf(table(inspector,"runtime.fields").getValueAt(0,2)).equals(after.x()+", "+after.y()),"Stable Inspector choice displayed old DTO values");check(!table(inspector,"runtime.fields").isCellEditable(0,2),"Runtime Inspector became editable");debugger.refresh(current.runtime(),current.snapshot());first.viewport().draw();second.viewport().draw();first.viewport().captureTo(work.resolve("fii4-game.png").toString());var captured=javax.imageio.ImageIO.read(work.resolve("fii4-game.png").toFile());boolean red=false;for(int y=0;y<captured.getHeight()&&!red;y++)for(int x=0;x<captured.getWidth();x++)if((captured.getRGB(x,y)&0xffffff)==0xff0000){red=true;break;}check(red,"Runtime Game Sprite GPU pixels are missing or hidden by the diagnostic box");return null;});
            var latency=new ArrayList<Double>();var sampling=new ArrayList<Double>();
            for(int i=0;i<50;i++){call(b,42);var update=b.latest();history(logs,update);long start=System.nanoTime();edt(()->{first.refresh(update.snapshot(),update.runtime());second.refresh(update.snapshot(),update.runtime());inspector.refresh(update.runtime());debugger.refresh(update.runtime(),update.snapshot());return null;});latency.add((System.nanoTime()-start)/1e6);sampling.add(edt(()->{long begun=System.nanoTime();profiler.refresh(update.runtime());return (System.nanoTime()-begun)/1e6;}));Thread.sleep(10);}
            Collections.sort(latency);Collections.sort(sampling);System.out.println("FII4_UI two_HWND_refresh_p50_ms="+latency.get(24)+" p95_ms="+latency.get(47)+" diagnostics_sample_p50_ms="+sampling.get(24)+" p95_ms="+sampling.get(47));
            Thread.sleep(500);edt(()->{for(var view:List.of(first,second)){var stats=view.viewport().frameStatistics();check(stats.length==6&&stats[0]>0&&stats[2]>=stats[1],"Native presentation percentile unavailable");System.out.println("FII4_PRESENTATION fps="+stats[0]+" frame_p50_ms="+stats[1]+" frame_p95_ms="+stats[2]+" extent="+stats[4]+"x"+stats[5]);}for(var window:owned)window.dispose();owned.clear();check(NativeViewport.metrics()[0]==initial[0],"Two-window teardown retained native surface");return null;});
            System.gc();Thread.sleep(1000);edt(()->null);long[] warm=edt(NativeViewport::metrics);
            for(int i=0;i<100;i++){var reply=b.latest();var owner=edt(()->{var game=new RuntimeGameView(command);game.refresh(reply.snapshot(),reply.runtime());return new WindowView(show(game),game);});edt(()->{try{owner.game().viewport().draw();check(owner.game().viewport().result().startsWith("PASS"),"Game frame failed: "+owner.game().viewport().result());}finally{owner.frame().dispose();}check(NativeViewport.metrics()[0]==initial[0],"Game close leaked surface");check(!owner.game().viewport().isPresenterRunning(),"Disposed Game presenter still running");return null;});}
            System.gc();Thread.sleep(1000);edt(()->null);long[] end=edt(NativeViewport::metrics);System.out.println("FII4_DISPOSAL cycles=100 surfaces="+end[0]+" handles_delta="+(end[1]-warm[1])+" gdi_delta="+(end[2]-warm[2])+" private_bytes_delta="+(end[4]-warm[4]));check(end[2]-warm[2]<20&&end[1]-warm[1]<40,"Native Game teardown resource growth");
            long privateWarm=end[4];
            for(int i=0;i<100;i++){var reply=b.latest();var owner=edt(()->{var game=new RuntimeGameView(command);game.refresh(reply.snapshot(),reply.runtime());return new WindowView(show(game),game);});edt(()->{try{owner.game().viewport().draw();check(owner.game().viewport().result().startsWith("PASS"),"Game frame failed: "+owner.game().viewport().result());}finally{owner.frame().dispose();}check(NativeViewport.metrics()[0]==initial[0],"Game close leaked surface");check(!owner.game().viewport().isPresenterRunning(),"Disposed Game presenter still running");return null;});}
            System.gc();Thread.sleep(1000);edt(()->null);long[] stable=edt(NativeViewport::metrics);System.out.println("FII4_STEADY_DISPOSAL total_cycles=200 surfaces="+stable[0]+" handles_delta="+(stable[1]-end[1])+" private_bytes_delta="+(stable[4]-privateWarm));check(stable[0]==initial[0]&&stable[1]-end[1]<40&&stable[2]-end[2]<20&&stable[4]-privateWarm<64L*1024*1024,"Repeated native Game window resource growth did not plateau");
            call(b,14);check(b.latest().runtime().entities().isEmpty(),"Stop retained live Runtime objects");
            for(int count:new int[]{10,100,1000}){
                if(count==1000)edt(()->{marker[0]=System.currentTimeMillis();logs.problem("F4 authoring history marker");return null;});
                var scene=b.latest().snapshot().documents().stream().filter(d->d.name().equals("Runtime load "+count)).findFirst().orElseThrow();
                call(b,41,"scene",Long.toUnsignedString(b.latest().runtime().session()),Long.toUnsignedString(scene.id()));call(b,13);call(b,42);var load=b.latest();history(logs,load);check(load.runtime().entityCount()==count,"Game load scene mismatch");
                var owner=edt(()->{var game=new RuntimeGameView(command);game.refresh(load.snapshot(),load.runtime());JFrame window=show(game);owned.add(window);return new WindowView(window,game);});
                edt(()->{owner.game().viewport().draw();owner.game().viewport().fit();return null;});var draws=new ArrayList<Double>();
                for(int i=0;i<20;i++){call(b,42);var update=b.latest();history(logs,update);draws.add(edt(()->{long start=System.nanoTime();owner.game().refresh(update.snapshot(),update.runtime());owner.game().viewport().draw();return (System.nanoTime()-start)/1e6;}));Thread.sleep(10);}
                Collections.sort(draws);long memory=edt(()->NativeViewport.profilerMetrics()[4]);System.out.println("FII4_GAME_LOAD entities="+count+" refresh_draw_p50_ms="+draws.get(9)+" p95_ms="+draws.get(18)+" ui_private_bytes="+memory);
                edt(()->{owner.frame().dispose();owned.remove(owner.frame());check(NativeViewport.metrics()[0]==initial[0],"Load Game window leaked a surface");return null;});call(b,14);history(logs,b.latest());
            }
            edt(()->{var console=table(logs.view("console"),"console.output");var sessions=new HashSet<String>();boolean timestamp=false;for(int row=0;row<console.getRowCount();row++){String session=String.valueOf(console.getValueAt(row,1));if(!session.endsWith(" / 0"))sessions.add(session);if(String.valueOf(console.getValueAt(row,7)).equals("F4 authoring history marker")){long time=java.time.Instant.parse(String.valueOf(console.getValueAt(row,0))).toEpochMilli();timestamp=time>=marker[0]&&time<=marker[0]+500&&time<System.currentTimeMillis()-100;}}check(sessions.size()>=2&&timestamp,"Late-open Console lost historical sessions or changed authoring timestamps");var problems=table(logs.view("problems"),"problems.output");check(java.util.stream.IntStream.range(0,problems.getRowCount()).noneMatch(row->String.valueOf(problems.getValueAt(row,3)).equals("Info")),"Late-open Problems contains info logs");return null;});
            System.out.println("PASS F-II.4 two owned HWNDs / one native session; native input/movement/readonly Inspector; real presentation 60/120; 100 Game window disposal cycles");
        }finally{edt(()->{owned.forEach(Window::dispose);return null;});}
    }
}
